INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('154a7732-9368-4c42-a3b6-ce832b1f45d4', '21feff02-016d-46e2-bb9d-c27495133b1b', '50. óra: Egybevágóság', 'Egybevágó alakzatok felismerése, fedésbe hozása eltolással, forgatással, tükrözéssel.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "701f6abb-4318-4326-a3e3-119a41cd4237", "text": "Mikor nevezünk két síkbeli alakzatot egybevágónak?", "type": "multiple-choice", "options": [{"id": "a8fa6cdb-e71f-4763-ace9-0e40f3dc48a9", "text": "Ha alakjuk és méretük pontosan megegyezik, mozgatással fedésbe hozhatók", "isCorrect": true}, {"id": "15a091da-2a5f-4e6a-a596-2387582f8388", "text": "Ha csak a színük egyezik", "isCorrect": false}, {"id": "879a1e82-e716-4d54-8b68-66c2f5e9da92", "text": "Ha a területük 0", "isCorrect": false}, {"id": "59bc3c78-a184-4c36-9469-1479a762cdba", "text": "Ha az egyik kétszer akkora", "isCorrect": false}], "timeLimit": 15}, {"id": "a0a03d87-a521-4144-a7aa-4abf0e81b9f8", "text": "Két egybevágó alakzat kerülete és területe megegyezik.", "type": "true-false", "options": [{"id": "14df9067-4734-44e5-a407-0eb3e4f18c4b", "text": "Igaz", "isCorrect": true}, {"id": "cba27f34-5a59-44a1-af49-9bc81dbf49ca", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dd13b22e-2203-4fb2-bd4d-995df775681f", "text": "Az eltolás, forgatás és tükrözés egybevágósági transzformációk.", "type": "true-false", "options": [{"id": "1dd277cd-77e8-4ceb-b817-5300afaf1ac5", "text": "Igaz", "isCorrect": true}, {"id": "e0e400b3-8399-40c4-a141-787f2cea1c8c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c2161dbc-61ef-48a4-b2f5-41a116c56550", "text": "Egy alakzat eltolása során megváltozik-e az alakzat területe?", "type": "true-false", "options": [{"id": "5c783189-46c1-4cda-9da1-aea78e659d38", "text": "Igaz", "isCorrect": false}, {"id": "f916833d-02a8-4086-b768-62d3075318d3", "text": "Hamis (a terület nem változik)", "isCorrect": true}], "timeLimit": 15}, {"id": "9ad72b71-4f15-4026-8b73-2b0dfb69bfb5", "text": "Melyik állítás HAMIS az egybevágó alakzatokról?", "type": "multiple-choice", "options": [{"id": "38ffca9a-4363-44c7-994a-9b4460efa8f4", "text": "A megfelelő oldalaik hossza eltérő", "isCorrect": true}, {"id": "05413663-c08e-4290-aef4-b985eb763e34", "text": "A megfelelő szögeik egyenlőek", "isCorrect": false}, {"id": "b14e414b-3601-4c6f-b2c6-46866663ba37", "text": "A megfelelő oldalaik hossza egyenlő", "isCorrect": false}, {"id": "766b3a9f-7ce2-4dc2-8086-556d63bfd897", "text": "Területük megegyezik", "isCorrect": false}], "timeLimit": 15}, {"id": "55a1161a-741c-4313-aeaf-6a34d298db6e", "text": "Minden négyzet egybevágó minden más négyzettel.", "type": "true-false", "options": [{"id": "d39db0a3-8875-45f8-88a2-25f2f3dab313", "text": "Igaz", "isCorrect": false}, {"id": "ac7124c6-2f86-446e-a948-a1d03ae62ba7", "text": "Hamis (csak akkor ha oldalhosszuk megegyezik)", "isCorrect": true}], "timeLimit": 15}, {"id": "4fb891d6-91a2-4756-b7a4-af9e6e145cd2", "text": "A tükrözés megtartja a szakaszok hosszát és a szögek nagyságát.", "type": "true-false", "options": [{"id": "2a87fe48-dbd1-4857-bd39-b6457b46b32a", "text": "Igaz", "isCorrect": true}, {"id": "8dc72bae-663a-4cf5-9dee-b4ae603b1ea4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('85f86c9b-de0b-418b-8cdf-ddee618a20be', '21feff02-016d-46e2-bb9d-c27495133b1b', '51. óra: A kör', 'A kör elemei: középpont (O), sugár (r), átmérő (d), húr, körív, körző használata.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "21c70b4b-7f0a-42ae-a86f-ec9fabdaa475", "text": "Hogyan viszonylik a kör átmérője (d) a sugárhoz (r)?", "type": "multiple-choice", "options": [{"id": "5297b634-0c8f-48ea-b95a-5fdae105f8e2", "text": "d = 2 * r (az átmérő a sugár kétszerese)", "isCorrect": true}, {"id": "4ac3c3ef-19a9-4132-9a48-2d0f80c292cf", "text": "d = r / 2", "isCorrect": false}, {"id": "7789a119-b972-4e0a-8079-62c39095b1cc", "text": "d = r + 5", "isCorrect": false}, {"id": "d887f1ba-7b74-404e-93ef-ce17fcb4088d", "text": "d = r * r", "isCorrect": false}], "timeLimit": 15}, {"id": "b6c76598-8c2e-4a21-a994-869f58b939f9", "text": "Ha a kör sugara r = 5 cm, mennyi az átmérője (d)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "89baba16-c9cb-42c7-8552-2a93cdf58555", "text": "Ha a kör átmérője d = 16 cm, mennyi a sugara (r)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "c42974d6-3284-4edb-9a51-57ba300aebf2", "text": "A körvonal pontjai a középponttól egyenlő távolságra (sugárnyira) vannak.", "type": "true-false", "options": [{"id": "d4d3c3a1-2721-4a10-9af8-86a4283e28ef", "text": "Igaz", "isCorrect": true}, {"id": "88190bd2-346e-42ec-b74b-bec5429e5bca", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eec72918-b165-46e6-9f3e-23c02b1d5863", "text": "Mi a kör leghosszabb húrja?", "type": "multiple-choice", "options": [{"id": "6e5eb04c-cd61-4915-9b27-e7bfbed18223", "text": "Az átmérő", "isCorrect": true}, {"id": "4c39fc75-ef15-4e12-bd68-831e7b1ab881", "text": "A sugár", "isCorrect": false}, {"id": "cb1f5c96-d21e-4b20-9f94-d5edb398b8b4", "text": "A körív", "isCorrect": false}, {"id": "65c28dff-2ae6-416b-a1ac-d850c965f20f", "text": "A körcikk", "isCorrect": false}], "timeLimit": 15}, {"id": "2a988446-6a88-4d4e-8e8f-0ed3db4f596a", "text": "A körző a körök rajzolására és távolságok másolására szolgáló szerkesztőeszköz.", "type": "true-false", "options": [{"id": "9be1e188-6003-480c-9597-6b1b118e365d", "text": "Igaz", "isCorrect": true}, {"id": "4ad3b8e2-9c92-45be-b27f-e4e468b6c61e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ca225733-ca69-47b4-9d5b-00b1468fc5a7", "text": "A kör belsejében lévő pontok távolsága a középponttól kisebb, mint a sugár.", "type": "true-false", "options": [{"id": "1b7707ae-fad5-4c53-ab6e-63d26420d8d8", "text": "Igaz", "isCorrect": true}, {"id": "78658d3f-e39b-4057-9b36-ba18cf22fac7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9f934f20-e3a8-4b43-a791-069846e329dc', '21feff02-016d-46e2-bb9d-c27495133b1b', '52. óra: A szakasz felezőmerőlegese', 'A szakaszfelező merőleges tulajdonságai, szerkesztése körzővel és vonalzóval.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "f6831031-279d-42fd-bd2f-6e823aa32c9f", "text": "Mi a szakaszfelező merőleges egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "9455b548-389e-4d5f-b228-45c53528c79c", "text": "A szakasz felezőpontján áthaladó, a szakaszra merőleges egyenes, melynek pontjai egyenlő távolságra vannak a szakasz két végpontjától", "isCorrect": true}, {"id": "241e065d-ad8e-4323-8582-f71aac82b4a8", "text": "A szakasszal párhuzamos egyenes", "isCorrect": false}, {"id": "cf2537b5-b56d-400a-a829-809f1da1de4a", "text": "A szakasz egyik végpontján átmenő egyenes", "isCorrect": false}, {"id": "acd533cb-bd60-450b-8c60-bcb19e882c99", "text": "Minden szakaszhoz 2 felezőmerőleges tartozik", "isCorrect": false}], "timeLimit": 15}, {"id": "c020a22e-d9e3-4509-a9a2-6ec6d0b8708d", "text": "Hány felezőmerőlegese van egy szakasznak a síkban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "6297fc16-b234-4a4f-9fc2-f8a1f9db763c", "text": "A szakaszfelező merőleges egyenes pontjai egyenlő távolságra vannak a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "d68165b0-79fe-45fa-8970-95b875ebfc46", "text": "Igaz", "isCorrect": true}, {"id": "9e6c1eac-3005-4530-b811-0c88128a5d72", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ebb4faa8-ff59-4658-b2b2-d3b490eb6be7", "text": "A szakasz felezőmerőlegesének megszerkesztéséhez a szakasz felénél nagyobb körzőnyílás szükséges.", "type": "true-false", "options": [{"id": "2f147ab3-1d15-4b22-b083-609615903d3b", "text": "Igaz", "isCorrect": true}, {"id": "25c80c0e-4393-47e6-b582-63b022e5c38d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "91516589-7c83-4160-a7ab-22f303d2f6cd", "text": "Hány fokos szöget zár be a felezőmerőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "f5b8d2a5-1c58-4f7d-8abf-9b72573afdfb", "text": "A háromszög oldalfelező merőlegesei egy pontban metszik egymást (a körülírt kör középpontjában).", "type": "true-false", "options": [{"id": "469b6df6-a16f-46da-9763-45981271f0d6", "text": "Igaz", "isCorrect": true}, {"id": "266ae877-3d5f-443d-aa07-56a114a14818", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "335efaab-462a-4ffb-9656-0931ddbf833e", "text": "Egy 8 cm-es szakasz felezőpontja a végponttól 4 cm-re van.", "type": "true-false", "options": [{"id": "56bd7460-7e25-42fc-87b4-17b1d36245bb", "text": "Igaz", "isCorrect": true}, {"id": "d8e0e13f-c2b2-4cac-869b-4017643777a7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e348cfc7-e96b-4b45-9914-d3b8730f333f', '21feff02-016d-46e2-bb9d-c27495133b1b', '53. óra: Szerkesztések', 'Alapszerkesztések: szakasz másolása, szög másolása, merőleges és párhuzamos állítása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "c0bd447e-f58a-4992-90d7-86ed1ea6e381", "text": "Milyen eszközt használunk körök és ívek rajzolásához szerkesztéskor?", "type": "multiple-choice", "options": [{"id": "de260dda-c06d-41f4-b4b9-0c542d5b76c8", "text": "Körzőt", "isCorrect": true}, {"id": "6606835f-3061-4a3a-a1a9-9bb1642def77", "text": "Szögmérőt", "isCorrect": false}, {"id": "cb7daf00-f849-4bca-b78d-d6c366b2319b", "text": "Radírt", "isCorrect": false}, {"id": "e1f4d149-399c-45ad-8068-b97573ff6eb7", "text": "Tollat", "isCorrect": false}], "timeLimit": 15}, {"id": "b159315c-7e8f-40cf-9cf1-edd3c03e66ce", "text": "Milyen vonalzót használunk a tiszta geometrikai szerkesztésekhez?", "type": "multiple-choice", "options": [{"id": "2787325a-0cf8-48a1-97fd-57d03100c611", "text": "Beosztás nélküli (egyenes) vonalzót", "isCorrect": true}, {"id": "cf93aa0b-8f46-44b6-b052-2f302b4210c4", "text": "Derékszögű vonalzót beosztással", "isCorrect": false}, {"id": "ce198f2d-6b5e-4646-9794-1008b1e966d2", "text": "Görbe vonalzót", "isCorrect": false}, {"id": "53e3cdeb-5101-4af5-9cde-9060234dc2d9", "text": "Mérőszalagot", "isCorrect": false}], "timeLimit": 15}, {"id": "474c98c3-b31b-4b0e-8540-8b074fe51843", "text": "Szakasz másolásakor körzővel mérjük fel a szakasz hosszát.", "type": "true-false", "options": [{"id": "04b71a79-e110-4a23-b355-24145dc2034b", "text": "Igaz", "isCorrect": true}, {"id": "6a50b9fe-b205-4086-8351-98acf8a0a47f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a55445b-832a-4876-a0ca-4c685c21eb6f", "text": "A szerkesztéseknél a körzőívek metszéspontjai adják meg a keresett pontokat.", "type": "true-false", "options": [{"id": "aebb5645-0421-4b5a-ba33-82754b895406", "text": "Igaz", "isCorrect": true}, {"id": "20645574-0ff6-4210-8896-29bf1dbc990c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d38c622b-5a09-4958-920d-f2a7d0372168", "text": "Hány fokos szöget zár be két egymásra merőleges egyenes?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "8c181a07-2bd8-4e0a-a85c-20510ecd5b61", "text": "Két párhuzamos egyenes sehol sem metszi egymást a síkban.", "type": "true-false", "options": [{"id": "138982f1-4688-4552-ac37-6adc2aada309", "text": "Igaz", "isCorrect": true}, {"id": "0cfa0294-9d84-42d6-a241-c6b79e603c9b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "15e0e0c8-9b79-4a64-87b3-5bf3a1228f03", "text": "A pontos és esztétikus szerkesztés alapkövetelmény a geometriában.", "type": "true-false", "options": [{"id": "7b4fb38b-a961-42b4-9340-58289b8d3fb6", "text": "Igaz", "isCorrect": true}, {"id": "c4a083ae-41c5-49ae-a6f4-5e759981c609", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e17b2cb1-2aea-433c-b8bd-ecaee069d1c0', '21feff02-016d-46e2-bb9d-c27495133b1b', '54. óra: Szerkesztések II.', 'Egyszerű szerkesztési feladatok: háromszög szerkesztése oldalaiból (SSSZ), háromszög-egyenlőtlenség.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "009ef738-029c-4ed8-a018-00994f9e0b9b", "text": "Mi a háromszög-egyenlőtlenség szabálya?", "type": "multiple-choice", "options": [{"id": "53651ddd-1e19-4e77-81ba-c876fa0fb74c", "text": "A háromszög bármely két oldalának összege nagyobb a harmadik oldalnál (a + b > c)", "isCorrect": true}, {"id": "97623cd0-ab5c-4dfe-a724-61b477e19a99", "text": "A három oldal összege 180", "isCorrect": false}, {"id": "75293ede-6056-496c-940d-67765e078e1c", "text": "A két rövidebb oldal összege kisebb a harmadiknál", "isCorrect": false}, {"id": "ed66c5eb-d214-4f5a-ac31-eb1d947662e4", "text": "Minden oldal egyenlő", "isCorrect": false}], "timeLimit": 15}, {"id": "643b9bf6-8712-44cc-9da6-b4f004e30c53", "text": "Szerkeszthető-e háromszög a 3 cm, 4 cm, 8 cm oldalakkal? (3+4 = 7 < 8)", "type": "true-false", "options": [{"id": "f682fadb-83a4-43f5-8e02-90025c53a5c9", "text": "Igaz", "isCorrect": false}, {"id": "a70733dd-b98c-485b-807b-dacaf8effa8a", "text": "Hamis (nem teljesül a háromszög-egyenlőtlenség)", "isCorrect": true}], "timeLimit": 15}, {"id": "e0a4e27e-22f9-4104-9bb6-59ff002acc47", "text": "Szerkeszthető-e háromszög 5 cm, 6 cm, 7 cm oldalakkal?", "type": "true-false", "options": [{"id": "a3e7b703-d4d3-415b-8e87-6de60e741183", "text": "Igaz (5+6 > 7)", "isCorrect": true}, {"id": "fbe0a8ab-fb9d-4409-ba2d-95ab8be760c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0d339893-ce04-486d-9a9b-0a461ac52147", "text": "Hány adatra van szükség legalább egy háromszög egyértelmű megszerkesztéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "3e0b6914-64b5-468d-a6b7-508e1b49c513", "text": "A háromszög szerkesztésének lépései: Vázlat -> Adatok -> Szerkesztés -> Ellenőrzés.", "type": "true-false", "options": [{"id": "a14f1009-05f4-4796-b53d-4f88f9435fda", "text": "Igaz", "isCorrect": true}, {"id": "46ce334a-30e2-4a77-8bb3-6beaa67a088b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b937bd46-cda7-46d2-b544-e11b14640aa5", "text": "Szerkeszthető-e háromszög 2 cm, 3 cm, 5 cm oldalakkal? (2+3 = 5)", "type": "true-false", "options": [{"id": "d056a8d0-3177-46e9-b03a-93caf1ab9943", "text": "Igaz", "isCorrect": false}, {"id": "1c289b85-b0de-4a3c-9a52-228b10407ed4", "text": "Hamis (kell hogy > legyen, nem =)", "isCorrect": true}], "timeLimit": 15}, {"id": "6842c771-f0dd-4d38-989a-2c5e0af421b0", "text": "Az egyenlő oldalú háromszög minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "b651d4b0-b616-487e-a13c-dbc67e36e1a6", "text": "Igaz", "isCorrect": true}, {"id": "2b8795ed-0b5f-47b4-ab58-d35a1ebf978e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d3001996-fea1-4af4-b468-bc56df8419a0', '21feff02-016d-46e2-bb9d-c27495133b1b', '55. óra: Számonkérés', 'Számonkérés a síkbeli alakzatokból és alapszerkesztésekből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "e6655ee9-e822-4f43-914d-f422f389be25", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "763f3893-a801-4954-8dbc-31e5fb4f4ce9", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "8d89da59-477f-4b07-978c-b93c1b2c8ba3", "text": "3. Szerkeszthető-e háromszög 4 cm, 5 cm, 10 cm oldalakkal?", "type": "true-false", "options": [{"id": "51d0b4fb-0509-4ca4-9687-5b9a4a675f7d", "text": "Igaz", "isCorrect": false}, {"id": "2d102dfd-1219-403c-b24f-da497b0f5ecb", "text": "Hamis (4+5 < 10)", "isCorrect": true}], "timeLimit": 15}, {"id": "dccceefb-aef3-4a43-88eb-7abed1d28f47", "text": "4. Ha a kör sugara 7 cm, mennyi az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "26793712-dba0-4ca5-8ae6-a9ef731f5c12", "text": "5. Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "0723526d-caca-4680-93f5-39d2b1bdbd90", "text": "6. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "a6ad2cfc-8237-4cf1-afe2-f720263f6a35", "text": "Igaz", "isCorrect": true}, {"id": "1e18c562-2178-4f05-8117-124610d2c12d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3abb00f9-8784-429e-9dd1-eb4aff5f53d0", "text": "7. Milyen szög a 120°-os szög?", "type": "multiple-choice", "options": [{"id": "b81a66b5-921e-4201-a051-5216e6981567", "text": "Tompaszög", "isCorrect": true}, {"id": "048aa694-4168-43ed-86dd-49d40366b834", "text": "Hegyesszög", "isCorrect": false}, {"id": "2286cf2e-c5e8-4f19-8e5d-b8d8eccde7a4", "text": "Derékszög", "isCorrect": false}, {"id": "41c764c2-8ac4-4932-a15e-e97cb948da11", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "cf0bf3fc-49e1-4d73-9841-5c8f26033358", "text": "8. Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "e282cbbb-26a9-42d3-9fec-63d4c63f5088", "text": "9. Az egybevágó alakzatok területe megegyezik.", "type": "true-false", "options": [{"id": "d78055f7-212e-4a38-8767-1b3a1d50b846", "text": "Igaz", "isCorrect": true}, {"id": "ca110bcc-bab3-4923-bb1d-43a005a1772d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aa072b17-983f-4772-a5ae-1da52f6ac31c", "text": "10. Hány fokosak a szabályos háromszög szögei?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('258b8cde-30a5-40b0-bbd0-dd654b42df33', '21feff02-016d-46e2-bb9d-c27495133b1b', '56. óra: Matematikai játékok', 'Geometriai kirakók (Tangram), alakzatok építése, stratégiák.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "e1f7d1b2-c4b0-41d1-a86e-4b26fe9adf58", "text": "Hány darabból (tanból) áll a klasszikus Tangram kirakó játék?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "689d85d1-91ea-43e8-813b-615427f25e88", "text": "Milyen síkidomokból áll a Tangram készlet?", "type": "multiple-choice", "options": [{"id": "029f863c-10c2-489a-baf3-f5b0ae3deb23", "text": "5 háromszög, 1 négyzet, 1 paralelogramma", "isCorrect": true}, {"id": "2c793ed1-6b4e-4965-90a0-a1b4ef766bb7", "text": "7 négyzet", "isCorrect": false}, {"id": "ae137c76-825c-474c-beb1-4c706ed69604", "text": "7 kör", "isCorrect": false}, {"id": "471d8757-f9bc-477f-9114-75ef4d8d6138", "text": "3 háromszög, 4 téglalap", "isCorrect": false}], "timeLimit": 15}, {"id": "da8a8a83-d38e-473d-b62d-c56d1f0005f2", "text": "A Tangram elemeiből sokféle figura (állatok, emberi alakok, tárgyak) kirakható.", "type": "true-false", "options": [{"id": "da41613f-375b-460c-be59-71516802bdc0", "text": "Igaz", "isCorrect": true}, {"id": "8fd96e58-4102-443c-8398-dae9dc50e068", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f52ae7aa-8265-4c66-baae-eaaa2d0e27eb", "text": "A kirakós játékok fejlesztik a térszemléletet és a síkbeli alakzatok felismerését.", "type": "true-false", "options": [{"id": "2afa2704-20e6-46b7-8216-e3ed547b6b13", "text": "Igaz", "isCorrect": true}, {"id": "056d699c-38b7-4889-8b56-81ae7916523b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4d36040-22e7-4f69-b8c5-9aa5aec979ac", "text": "A szabályos sokszögekkel hégmentesen lefedhető a sík (pl. szabályos hatoszögekkel).", "type": "true-false", "options": [{"id": "71b0d0c0-dd6f-42f6-a4f8-faf93d301de1", "text": "Igaz", "isCorrect": true}, {"id": "09138b28-795d-4f49-8236-22e5ae8f3a28", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "20f77a53-dbbf-4208-9d04-f5d9026b359e", "text": "Hány oldala van a szabályos hexagonnak (hatszögnek)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "84bd9855-aa04-4cff-b6ca-4a7e5d946da7", "text": "A geometriai játékok során a próbálgatás és a logikai tervezés együtt segít a megoldásban.", "type": "true-false", "options": [{"id": "1925d663-2b7e-4a8e-9901-84a65e2b9750", "text": "Igaz", "isCorrect": true}, {"id": "d629b80f-311a-4d15-ab59-fbf4ba219f81", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cd14e92c-a969-42a7-b9a8-95444e87c000', '21feff02-016d-46e2-bb9d-c27495133b1b', '57. óra: Tengelyes tükrözés', 'Tengelyes tükrözés fogalma, tengely (t), tárgy és tükörkép (A és A'').', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "3044f0cd-133e-463f-9840-68e2c30e94e7", "text": "Mi a tengelyes tükrözés lényege egy ''t'' tengelyre nézve?", "type": "multiple-choice", "options": [{"id": "ac5bcd2f-4a9b-47e3-a79a-7ae0b4dcd6e3", "text": "A pont és tükörképe a tengelyre merőleges egyenesen van, és egyenlő távolságra van a tengelytől", "isCorrect": true}, {"id": "12816632-5f01-43d3-974f-ff640b220f67", "text": "A pontot eltoljuk párhuzamosan", "isCorrect": false}, {"id": "b78beba8-ed33-4ce0-9810-15ec1279bf6b", "text": "A pontot elforgatjuk 180 fokkal", "isCorrect": false}, {"id": "3d05472c-390f-4b0f-8e6a-7ae7eb2d7c29", "text": "A pontot lefelé mozgatjuk 5 cm-rel", "isCorrect": false}], "timeLimit": 15}, {"id": "8efadf53-cd4f-4eb6-bccc-c63177ef8d7e", "text": "Hol van a tengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "ba671c0b-d1a8-4d4a-a9fe-fdb0d6ccf748", "text": "Önmagában (fixpont)", "isCorrect": true}, {"id": "d566ee41-821f-4d86-9205-85993129e451", "text": "Az origóban", "isCorrect": false}, {"id": "d4d58324-bf6f-461f-8dba-09735666e950", "text": "Végtelenben", "isCorrect": false}, {"id": "7bc3be44-90f2-4870-90d0-b6fb808e0d4e", "text": "A tengely másik végén", "isCorrect": false}], "timeLimit": 15}, {"id": "a944df1d-fc45-4317-82b3-1156beb7ff3d", "text": "Ha a P pont 4 cm-re van a tükörtengelytől, milyen messze van a P'' tükörkép a tengelytől?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "38b5f186-d61e-4728-9aac-71a4846a51b3", "text": "Milyen messze van a P pont a P'' tükörképétől, ha a tengelytől való távolsága 4 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "fa1fbca4-4041-46c5-bb91-44f318c142bb", "text": "A tengelyes tükrözés egybevágósági transzformáció.", "type": "true-false", "options": [{"id": "e3255e79-71b6-461e-b1d9-4b6600f64f3f", "text": "Igaz", "isCorrect": true}, {"id": "9ead64b8-dfb6-46dc-bacb-c26aea8905fa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b0729891-493c-4ae8-8c75-c8e9f94723c6", "text": "A tengelyes tükrözés megváltoztatja az alakzat körüljárási irányát (pl. óramutató járásával megegyezőből ellentétes lesz).", "type": "true-false", "options": [{"id": "5d7b4b29-e74d-4636-9f58-29fb00b5abc1", "text": "Igaz", "isCorrect": true}, {"id": "cb983058-0c6c-4d43-861b-398dc90623dc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9ca36c2a-919c-418e-8a70-1034ec147823", "text": "A tengelyesen tükrös alakzat és tükörképe egybevágó.", "type": "true-false", "options": [{"id": "c4a48591-1274-4f57-b216-8a03b8bdeca9", "text": "Igaz", "isCorrect": true}, {"id": "3b574b1e-cb41-4367-8274-adb0f3d56a3a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('db70b7dc-4805-468f-913e-2086be018ff9', '21feff02-016d-46e2-bb9d-c27495133b1b', '58. óra: A tengelyes tükrözés tulajdonságai', 'Távolságtartás, szögtartás, körüljárási irány megváltozása, egyenes és kör tükörképe.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "d132c775-0569-47bf-b93a-ad173d33a519", "text": "Melyik tulajdonság érvényes a tengelyes tükrözésre?", "type": "multiple-choice", "options": [{"id": "897b4851-593d-4e4a-85fc-1864d693bf30", "text": "Távolságtartó, szögtartó, egyenestartó és megváltoztatja a körüljárási irányt", "isCorrect": true}, {"id": "4cc4f22c-a35f-46b1-83d8-e03fc460f735", "text": "Növeli a szakaszok hosszát", "isCorrect": false}, {"id": "8ffd75ba-bfa9-4a41-8a10-07b2d685d7fc", "text": "Megváltoztatja a szögek nagyságát", "isCorrect": false}, {"id": "770432d5-a621-42e1-9a97-c17e26c3f31b", "text": "Négyszögből háromszöget csinál", "isCorrect": false}], "timeLimit": 15}, {"id": "de98defa-6239-4527-97bc-1454ff9ee09b", "text": "Egy 5 cm-es szakasz tengelyes tükörképe is 5 cm hosszú.", "type": "true-false", "options": [{"id": "223bf607-f87c-48e7-aeac-e57a0ef4344e", "text": "Igaz (távolságtartó)", "isCorrect": true}, {"id": "3669ccd9-e873-4e87-80fe-32567cd0d2a4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d5c1b6c3-0b5f-4f50-aa7c-144d341be857", "text": "Egy 45°-os szög tengelyes tükörképe is 45°-os.", "type": "true-false", "options": [{"id": "0ad422c2-4ef9-4590-94a4-8669febe4635", "text": "Igaz (szögtartó)", "isCorrect": true}, {"id": "1438c88e-6b07-46e3-a93f-625f2928886f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3ccf2088-aa97-4d54-ac6e-39d86da5d4fd", "text": "A tengelyre merőleges egyenes tükörképe önmaga (önmagába transzformálódik).", "type": "true-false", "options": [{"id": "02e4693d-dcc5-4196-ba04-7009e86eb093", "text": "Igaz", "isCorrect": true}, {"id": "b56c765a-8544-415c-ad6e-bb5c03c5b32d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d5821b09-4bc3-4a72-bcf8-57ac1863b36e", "text": "Egy kör tengelyes tükörképe ugyanolyan sugarú kör.", "type": "true-false", "options": [{"id": "23833a25-1498-4e4c-a67e-8d6b40b21560", "text": "Igaz", "isCorrect": true}, {"id": "b7e34d32-df7f-4333-afe4-08eadce5e50b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "40ff5b82-a4a2-4270-ade3-0e1c1fbefd4d", "text": "A tengellyel párhuzamos egyenes tükörképe is párhuzamos a tengellyel.", "type": "true-false", "options": [{"id": "a14b78e3-d1d1-46c0-9741-a09660f39257", "text": "Igaz", "isCorrect": true}, {"id": "b7c6694d-5343-4f59-99af-82742d4f40bd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b26defd3-94fb-42d8-a314-6ec8a93c676b", "text": "Hány fixpontja (helyben maradó pontja) van a tengelyes tükrözésnek a síkban?", "type": "multiple-choice", "options": [{"id": "f8ed0f88-58ce-44e4-bbdd-c53c2c446ab3", "text": "Végtelen sok (a tükörtengely minden pontja)", "isCorrect": true}, {"id": "a730fd21-38b2-47f4-807e-3ecfff6b8a49", "text": "Csak 1", "isCorrect": false}, {"id": "65ae197b-83c8-450c-af44-15d54e681d85", "text": "Nincs egy sem", "isCorrect": false}, {"id": "0d6c3af4-c09f-43a7-9f54-282a451e59df", "text": "Pontosan 2", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b03f0e30-7c92-4375-b989-bbf3f06938c6', '21feff02-016d-46e2-bb9d-c27495133b1b', '59. óra: Gyakorlóóra', 'Tengelyes tükörkép szerkesztésének gyakorlása pontok, szakaszok, sokszögek esetén.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "551f0ed5-3cc0-415c-a6eb-2563edc39c80", "text": "Hogyan szerkesztjük meg egy P pont ''t'' tengelyre vonatkozó tükörképét?", "type": "multiple-choice", "options": [{"id": "4f00a1fe-c7b0-4e8a-ac11-b0709f1825d4", "text": "Merőlegest állítunk P-ből ''t''-re, és a talpponttól felmérjük a P távolságát a merőlegesre", "isCorrect": true}, {"id": "5cd51598-f811-4a61-bb20-a434ba833533", "text": "Párhuzamost húzunk ''t''-vel", "isCorrect": false}, {"id": "80acb0c8-3fa4-4398-99d0-a90d4cfc4ae8", "text": "Körzővel kört rajzolunk P középponttal", "isCorrect": false}, {"id": "4735d4b7-a6bb-4654-a01f-d770743d105b", "text": "Összekötjük P-t az origóval", "isCorrect": false}], "timeLimit": 15}, {"id": "222036d4-a9dc-4493-b25c-3e9ab5255aa8", "text": "Egy háromszög tengelyes tükrözése után a kapott háromszög területe megegyezik az eredetivel.", "type": "true-false", "options": [{"id": "62fd7aea-842a-40e2-969f-588e040dda47", "text": "Igaz", "isCorrect": true}, {"id": "27ab6be3-8435-410e-8992-c53d48671907", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3cf756af-82d5-4714-bf4a-d6caf510cd39", "text": "Ha a P pont a tengelyen van, hol van a tükörképe?", "type": "multiple-choice", "options": [{"id": "51c96e32-dc80-4d6f-a701-f7082a7b31a7", "text": "Önmagában (P = P'')", "isCorrect": true}, {"id": "ec139758-952a-468b-b85e-055bdf180b8d", "text": "A tengely másik oldalán", "isCorrect": false}, {"id": "f3fe1b38-a057-47ab-a89a-d7fd9e912c8a", "text": "A sík szélén", "isCorrect": false}, {"id": "eca8da88-c14c-4588-a8c6-3e45cddcac91", "text": "Az origóban", "isCorrect": false}], "timeLimit": 15}, {"id": "47b8285b-6254-4a0f-8cff-5db691a72790", "text": "A szakasz felezőmerőlegese a szakaszt önmagára tükrözi vissza.", "type": "true-false", "options": [{"id": "d4034461-672c-4e21-8a42-e340e617ea01", "text": "Igaz", "isCorrect": true}, {"id": "d629220e-6446-4ea8-81dd-57b1bb7bd995", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4ad71fb1-c1f7-48b3-9322-f17aab0d56f5", "text": "Melyik betűnek VAN függőleges szimmetriatengelye? (pl. A, M, Y, W)", "type": "multiple-choice", "options": [{"id": "ce133ccd-77f5-4b35-a9a8-77b07bc00d9d", "text": "A", "isCorrect": true}, {"id": "ccef3cd0-bc8d-40e8-869a-2f6d177fe5c1", "text": "F", "isCorrect": false}, {"id": "8a6fc9b0-2faf-4de3-9b2a-c45e435958d2", "text": "L", "isCorrect": false}, {"id": "376903d4-dc75-4ebb-96f8-752b04113518", "text": "R", "isCorrect": false}], "timeLimit": 15}, {"id": "71e021e2-73ac-42e4-8d1d-c270e75f1c14", "text": "Melyik betűnek VAN vízszintes szimmetriatengelye? (pl. B, C, D, E, K)", "type": "multiple-choice", "options": [{"id": "50a127d4-450d-4283-8600-da88e2908b31", "text": "E", "isCorrect": true}, {"id": "88985e5f-f1b2-492d-b633-fbf64edbdb58", "text": "F", "isCorrect": false}, {"id": "73906d0c-6795-4d17-b9e5-93051051fb1a", "text": "G", "isCorrect": false}, {"id": "83160df9-1128-46da-8643-fb8d78603d18", "text": "J", "isCorrect": false}], "timeLimit": 15}, {"id": "7a18b402-d81f-4554-8fcd-ad2525f2b0cd", "text": "A tengelyesen tükrös alakzatok szimmetrikusak a tükörtengelyre.", "type": "true-false", "options": [{"id": "17fea5a3-f687-48f7-bf1c-6db89c72fa0c", "text": "Igaz", "isCorrect": true}, {"id": "98dd5d15-3236-42af-9d5a-6c2ac7c154b5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());